# Refuses (exit 11) when HDRP_v<V> is the live build (PLAY.bat), the previous build (PLAY_PREV.bat), the -Build base, any build a Builds\*.bat launcher names, or a folder a running HadesSlice started from; also when V is not a 2-3 letter v109 tag (deploy_data refuses longer; the exit-10 guard below stays).
$P0 = $env:FK_ROOT; $Vn = ("$V" -replace '^v', ''); $tgtName = "HDRP_v$Vn"; $tgtDir = "$P0\Builds\$tgtName"; $refuse = $null
function Bat-Build($f) { $t = "$P0\Builds\$f"; if (Test-Path $t) { return ([regex]::Match((Get-Content $t -Raw), 'HDRP_\w+')).Value } else { return '' } }
$liveB = Bat-Build 'PLAY.bat'; $prevB = Bat-Build 'PLAY_PREV.bat'; $baseB = $(if ($Build) { ([regex]::Match($Build, 'HDRP_\w+')).Value } else { '' })
if ($Vn -notmatch '^109[a-z]{2,3}$') { $refuse = "V tag '$V' is not a 2-3 letter v109 tag (QA copies are only made for tags like 109xx)" }
elseif ($tgtName -eq $liveB) { $refuse = "$tgtName is the LIVE build named by Builds\PLAY.bat" }
elseif ($tgtName -eq $prevB) { $refuse = "$tgtName is the PREVIOUS build named by Builds\PLAY_PREV.bat" }
elseif ($baseB -and $tgtName -eq $baseB) { $refuse = "$tgtName is the -Build base this run copies from" }
else {
  foreach ($bf in @(Get-ChildItem "$P0\Builds" -Filter *.bat -File -EA SilentlyContinue)) { if ((Get-Content $bf.FullName -Raw -EA SilentlyContinue) -match ([regex]::Escape($tgtName) + '\b')) { $refuse = "$tgtName is named by launcher Builds\$($bf.Name)"; break } }
  if (-not $refuse) { foreach ($pr in @(Get-CimInstance Win32_Process -Filter "Name='HadesSlice.exe'" -EA SilentlyContinue)) { if (("$($pr.ExecutablePath)" -like "$tgtDir\*") -or ("$($pr.CommandLine)" -like "*$tgtDir\*")) { $refuse = "$tgtName is in use by a running HadesSlice (pid $($pr.ProcessId))"; break } } }
}
